    private static InputBox Input()=>new(){MinHeight=34,Margin=new Thickness(2),Background=new SolidColorBrush(Color.FromRgb(28,32,44)),Foreground=Brushes.White,Padding=new Thickness(5)};
    private static CheckBox Check(string title)=>new(){Content=title,MinHeight=36,Margin=new Thickness(4),Foreground=Brushes.White};
    private static ComboBox Choice(string[] values){var c=new ComboBox{MinHeight=36,Margin=new Thickness(3)};foreach(var s in values)c.Items.Add(s);return c;}
    private static Slider Slide(int min,int max)=>new(){Minimum=min,Maximum=max,TickFrequency=1,IsSnapToTickEnabled=true,Margin=new Thickness(5)};
    private static Button Action(string title,Action action){var b=new Button{Content=title,MinHeight=40,Padding=new Thickness(8),Margin=new Thickness(3)};b.Click+=(_,_)=>action();return b;}
    private static void Section(StackPanel p,string title,(string,Control)[] controls){var inner=new StackPanel();foreach(var (text,c) in controls){inner.Children.Add(new TextBlock{Text=text,Margin=new Thickness(4)});inner.Children.Add(c);}p.Children.Add(new Expander{Header=title,Content=inner,IsExpanded=true,Foreground=Brushes.White});}
    private static void AddSlider(StackPanel p,string text,Slider slider,string format){var label=new TextBlock{Margin=new Thickness(4)};void Update()=>label.Text=text+": "+slider.Value.ToString(format,CultureInfo.InvariantCulture);slider.ValueChanged+=(_,_)=>Update();Update();p.Children.Add(label);p.Children.Add(slider);}
    private void Coordinates(StackPanel panel,string key,string title){var grid=new UniformGrid{Columns=4};var inputs=new List<InputBox>();foreach(var label in new[]{"اليسار","الأعلى","العرض","الارتفاع"}){var cell=new StackPanel();cell.Children.Add(new TextBlock{Text=label,FontSize=12,Margin=new Thickness(3)});var input=Input();input.FlowDirection=FlowDirection.LeftToRight;inputs.Add(input);cell.Children.Add(input);grid.Children.Add(cell);input.LostKeyboardFocus+=(_,_)=>ApplyCoordinates(key);input.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){ApplyCoordinates(key);e.Handled=true;}};}coordinates[key]=inputs.ToArray();panel.Children.Add(new Expander{Header=title,Content=grid,IsExpanded=true,Foreground=Brushes.White});}
    private void ApplyCoordinates(string key){if(updating||Selected is not {} a)return;try{var n=coordinates[key].Select(t=>double.Parse(new string(t.Text.Trim().TrimEnd('%','٪').Select(c=>char.IsDigit(c)?(char)('0'+char.GetNumericValue(c)):c).ToArray()).Replace(',','.').Replace('٫','.'),CultureInfo.InvariantCulture)/100).ToArray();if(n.Any(x=>!double.IsFinite(x))||n[2]<.03||n[3]<.03)throw new FormatException();var b=ReadingArea.Bound(new(n[1],n[1]+n[3],n[0],n[0]+n[2]));Edit(x=>key=="source"?x with{Source=b}:x with{Output=b,Appearance=(x.Appearance??new()) with{Position="custom"}});LoadSelection();}catch(FormatException){note.Text="أدخل نسبًا صحيحة: يسار، أعلى، عرض، ارتفاع. أصغر ضلع 3%.";}}
    private void UpdateCoordinates(){if(Selected is not {} a)return;bool old=updating;updating=true;foreach(var key in new[]{"source","output"}){var b=key=="source"?a.Source:a.PresentationOutput();var n=new[]{b.Left,b.Top,b.Right-b.Left,b.Bottom-b.Top};for(int i=0;i<4;i++){coordinates[key][i].Text=(n[i]*100).ToString("0.0",CultureInfo.InvariantCulture);coordinates[key][i].IsReadOnly=false;}}updating=old;}
    private void AppearanceChanged(){if(updating)return;Edit(a=>a with{Structured=structured.IsChecked==true,AutoDetect=autoDetect.IsChecked==true,Appearance=new(Font:CaptionAppearance.Fonts[Math.Max(0,font.SelectedIndex)],Backdrop:CaptionAppearance.Backdrops[Math.Max(0,back.SelectedIndex)],Align:H[Math.Max(0,align.SelectedIndex)],Vertical:V[Math.Max(0,vertical.SelectedIndex)],Position:CaptionAppearance.Positions[Math.Max(0,placement.SelectedIndex)],MatchSize:match.IsChecked==true,SpeakerColors:speaker.IsChecked==true,SpeakerColor:Colors[Math.Max(0,palette.SelectedIndex)],Outline:outline.IsChecked==true,FadeMs:(int)fade.Value,Accent:accent.IsChecked==true,CoverMinimum:coverMin.IsChecked==true,CoverEarly:early.IsChecked==true,StackUp:stack.IsChecked==true,Ride:ride.IsChecked==true,ReviewedOnly:reviewed.IsChecked==true,CenterOnly:centerOnly.IsChecked==true,AccentOpacity:(int)accentOpacity.Value,AccentStrength:(int)accentStrength.Value)});}
    private void Add(ReadingArea area){var existing=areas.FindIndex(a=>a.Kind==area.Kind);if(existing>=0){list.SelectedIndex=existing;note.Text="البطاقة موجودة بالفعل؛ يمكنك تعديلها أو حذفها من الزر الواضح أعلاه.";return;}if(areas.Count>=9){note.Text="حتى 8 مناطق إضافية لحماية الأداء.";return;}areas.Add(area.Validate());Rebuild(areas.Count-1);Save();}
    private void Remove(){if(list.SelectedIndex<=0)return;var i=list.SelectedIndex;areas.RemoveAt(i);Rebuild(Math.Min(i,areas.Count-1));Save();}
    private void Rebuild(int index){updating=true;list.Items.Clear();foreach(var a in areas)list.Items.Add(a.Name);updating=false;list.SelectedIndex=index;LoadSelection();}
    private void LoadSelection(){if(updating||Selected is not {} a)return;updating=true;name.Text=a.Name;name.IsEnabled=a.Id!="dialogue";enabled.IsChecked=a.Enabled;enabled.IsEnabled=a.Id!="dialogue";size.Value=a.FontSize;opacity.Value=a.Background;duration.Value=a.DurationMs;duration.IsEnabled=a.Id!="dialogue";interval.Value=a.IntervalMs;interval.IsEnabled=a.Id!="dialogue";structured.IsEnabled=a.Id!="dialogue";structured.IsChecked=a.Structured;autoDetect.IsChecked=a.AutoDetect;autoDetect.IsEnabled=a.Kind is ReadingAreaKind.Phone or ReadingAreaKind.Notification or ReadingAreaKind.Menu;var s=a.Appearance??new();font.SelectedIndex=Array.IndexOf(CaptionAppearance.Fonts,s.Font);back.SelectedIndex=Array.IndexOf(CaptionAppearance.Backdrops,s.Backdrop);align.SelectedIndex=Array.IndexOf(H,s.Align);vertical.SelectedIndex=Array.IndexOf(V,s.Vertical);placement.SelectedIndex=Array.IndexOf(CaptionAppearance.Positions,s.Position);palette.SelectedIndex=Array.IndexOf(Colors,s.SpeakerColor);match.IsChecked=s.MatchSize;outline.IsChecked=s.Outline;speaker.IsChecked=s.SpeakerColors;fade.Value=s.FadeMs;accent.IsChecked=s.Accent;accentOpacity.Value=s.AccentOpacity;accentStrength.Value=s.AccentStrength;coverMin.IsChecked=s.CoverMinimum;early.IsChecked=s.CoverEarly;stack.IsChecked=s.StackUp;ride.IsChecked=s.Ride;reviewed.IsChecked=s.ReviewedOnly;centerOnly.IsChecked=s.CenterOnly;foreach(var option in new[]{coverMin,early,stack,ride,centerOnly})option.IsEnabled=a.Kind==ReadingAreaKind.Dialogue;reviewed.IsEnabled=true;updating=false;UpdateCoordinates();Render();}
    private void Edit(Func<ReadingArea,ReadingArea> change){if(updating||Selected is not {} a)return;areas[list.SelectedIndex]=change(a).Validate();saveTimer.Stop();saveTimer.Start();UpdateCoordinates();Render();}
    private void Save(){controller.DialogueOutput=areas[0].Output;controller.Settings=controller.Settings with{Region=areas[0].Source,Style=controller.Settings.Style with{FontSize=areas[0].FontSize,Background=areas[0].Background,Appearance=areas[0].Appearance,StackPrevious=false}};controller.ReadingAreas=areas.Skip(1).ToArray();note.Text="حُفظ التخطيط. تعديل المظهر لا يغير مفتاح المحرك أو النموذج.";}
    private void Export(){Save();var dialog=new Microsoft.Win32.SaveFileDialog{Filter="ArabicGames layout (*.json)|*.json",FileName="ArabicGames-GTA6-Layout.json"};if(dialog.ShowDialog()==true)System.IO.File.WriteAllText(dialog.FileName,new ReadingLayout(1,areas.ToArray()).Export());}
    private void Import(){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="ArabicGames layout (*.json)|*.json"};if(dialog.ShowDialog()!=true)return;try{var imported=ReadingLayout.Import(System.IO.File.ReadAllText(dialog.FileName));areas.Clear();var dialogue=imported.Areas.Single(a=>a.Kind==ReadingAreaKind.Dialogue) with{Id="dialogue"};areas.Add(dialogue);areas.AddRange(imported.Areas.Where(a=>a.Kind!=ReadingAreaKind.Dialogue));Rebuild(0);Save();}catch(Exception e)when(e is ArgumentException or System.Text.Json.JsonException or System.IO.IOException){note.Text="لم نستورد الملف: "+e.Message;}}
    private void FirstLive(){if(receivedLive)return;receivedLive=true;demo.IsChecked=false;}
    private void LiveArea(AreaCaption c){if(c.Clear){live.Remove(c.Id);rendered.Remove(c.Id);}else{live[c.Id]=(c,Environment.TickCount64+c.DurationMs);FirstLive();}Render();}
    private void LiveDialogue(string text,int ms,GameTranslator.Core.TextBox? box){liveDialogue=text;liveBox=box;dialogueUntil=Environment.TickCount64+ms;FirstLive();Render();}
    private void ClearLive(){live.Clear();rendered.Clear();Render();}
    private void Refresh(){
        if(!IsVisible)return;if(Selected is {} selected){var status=controller.ReadingAreaStatus(selected.Id);if(areaState.Text!=status)areaState.Text=status;}if(controller.LastFrame is {} f&&!ReferenceEquals(last,f)){last=f;if(previewBitmap is null||previewBitmap.PixelWidth!=f.Width||previewBitmap.PixelHeight!=f.Height){previewBitmap=new WriteableBitmap(f.Width,f.Height,96,96,PixelFormats.Bgra32,null);image.Source=previewBitmap;RenderOptions.SetBitmapScalingMode(image,BitmapScalingMode.LowQuality);}previewBitmap.WritePixels(new Int32Rect(0,0,f.Width,f.Height),f.Pixels,f.Stride,0);}
        var expired=live.Where(x=>Environment.TickCount64>=x.Value.Until).Select(x=>x.Key).ToArray();foreach(var id in expired){live.Remove(id);rendered.Remove(id);}if(expired.Length>0||dialogueUntil>0&&Environment.TickCount64>=dialogueUntil){dialogueUntil=0;Render();}
    }
    private void RenderLive(){
        foreach(var (id,state) in live){if(Environment.TickCount64>=state.Until)continue;var c=state.Caption;var area=areas.FirstOrDefault(x=>x.Id==id);if(area is null)continue;
            if(!rendered.TryGetValue(id,out var cached)||!ReferenceEquals(cached.Caption,c)){
                var visual=c.Panel is {} panel?CaptionVisual.Panel(panel,area):CaptionVisual.Text(c.Text,c.Appearance,c.FontSize*1280d/1920,c.Background);
                cached=(c,visual);rendered[id]=cached;
            }
            var v=cached.Visual;v.Width=(c.Output.Right-c.Output.Left)*1280;v.Height=(c.Output.Bottom-c.Output.Top)*720;v.IsHitTestVisible=false;Canvas.SetLeft(v,c.Output.Left*1280);Canvas.SetTop(v,c.Output.Top*720);canvas.Children.Add(v);
        }
        if(Environment.TickCount64<dialogueUntil&&!string.IsNullOrWhiteSpace(liveDialogue))DrawPreview(areas[0],liveDialogue,liveBox);
    }
    private void DrawPreview(ReadingArea area,string text,GameTranslator.Core.TextBox? source=null){
        var a=area.Appearance??new();var box=a.Position=="custom"?area.Output:source is {} b?new CropRegion(b.Top,b.Bottom,b.Left,b.Right):area.Source;
        var visual=CaptionVisual.Text(text,a,CaptionSizing.FontPixels(area.FontSize,1280,720,a.MatchSize,source is not null?controller.LastCaptionLineHeight:null),area.Background);visual.MaxWidth=(box.Right-box.Left)*1280;visual.IsHitTestVisible=false;visual.Measure(new Size(visual.MaxWidth,double.PositiveInfinity));
        double w=visual.DesiredSize.Width,h=visual.DesiredSize.Height,x=box.Left*1280+(a.Align=="right"?(box.Right-box.Left)*1280-w:a.Align=="left"?0:((box.Right-box.Left)*1280-w)/2),y=box.Top*720;
        y=a.Position switch{"above"=>y-h-4,"below"=>box.Bottom*720+4,"cover"=>y+((box.Bottom-box.Top)*720-h)/2,_=>y+(a.Vertical=="top"?0:a.Vertical=="center"?((box.Bottom-box.Top)*720-h)/2:(box.Bottom-box.Top)*720-h)};
        Canvas.SetLeft(visual,Math.Clamp(x,0,Math.Max(0,1280-w)));Canvas.SetTop(visual,Math.Clamp(y,0,Math.Max(0,720-h)));canvas.Children.Add(visual);
    }
    private void Render(){canvas.Children.Clear();canvas.Children.Add(image);if(demo.IsChecked!=true)RenderLive();foreach(var a in areas){Draw(a,a.Source,false);Draw(a,a.PresentationOutput(),true);}if(demo.IsChecked==true&&Selected is {} selectedArea)DrawPreview(selectedArea,sample.Text);}
    private void Draw(ReadingArea a,CropRegion b,bool output){bool selected=Selected?.Id==a.Id;Brush color=!a.Enabled?Brushes.Gray:output?Brushes.DeepSkyBlue:Brushes.Gold;var rect=new Rectangle{Width=(b.Right-b.Left)*1280,Height=(b.Bottom-b.Top)*720,Stroke=color,StrokeThickness=selected?3:1.5,StrokeDashArray=output?new DoubleCollection{4,3}:null,Fill=new SolidColorBrush(Color.FromArgb(selected?(byte)12:(byte)2,0,160,200)),IsHitTestVisible=false};Canvas.SetLeft(rect,b.Left*1280);Canvas.SetTop(rect,b.Top*720);canvas.Children.Add(rect);var label=new TextBlock{Text=(output?"الترجمة · ":"القراءة · ")+a.Name,Foreground=Brushes.Black,Background=color,FontSize=17,IsHitTestVisible=false,FlowDirection=FlowDirection.RightToLeft};Canvas.SetLeft(label,b.Left*1280);Canvas.SetTop(label,Math.Max(0,b.Top*720-25));canvas.Children.Add(label);if(selected)foreach(var p in Handles(b)){var square=new Rectangle{Width=12,Height=12,Fill=color,Stroke=Brushes.Black,IsHitTestVisible=false};Canvas.SetLeft(square,p.X-6);Canvas.SetTop(square,p.Y-6);canvas.Children.Add(square);}}
    private static Point[] Handles(CropRegion b){double l=b.Left*1280,r=b.Right*1280,t=b.Top*720,d=b.Bottom*720;return [new(l,t),new((l+r)/2,t),new(r,t),new(r,(t+d)/2),new(r,d),new((l+r)/2,d),new(l,d),new(l,(t+d)/2)];}
    private void Begin(Point p){if(Selected is not {} a)return;anchor=p;handle=-1;if(!draw){bool found=false;foreach(var output in new[]{true,false}){var b=output?a.PresentationOutput():a.Source;var handles=Handles(b);for(int i=0;i<8;i++)if((handles[i]-p).Length<17){handle=i;found=true;break;}if(found){dragOutput=output;break;}}if(!found){foreach(var area in areas.AsEnumerable().Reverse()){foreach(var output in new[]{true,false}){var b=output?area.PresentationOutput():area.Source;if(p.X>=b.Left*1280&&p.X<=b.Right*1280&&p.Y>=b.Top*720&&p.Y<=b.Bottom*720){list.SelectedIndex=areas.IndexOf(area);a=area;dragOutput=output;found=true;break;}}if(found)break;}if(!found)return;}}original=dragOutput?a.PresentationOutput():a.Source;dragging=true;}
    private void Move(Point p){if(Selected is not {} a)return;double dx=(p.X-anchor.X)/1280,dy=(p.Y-anchor.Y)/720;CropRegion b;if(draw)b=new(Math.Min(anchor.Y,p.Y)/720,Math.Max(anchor.Y,p.Y)/720,Math.Min(anchor.X,p.X)/1280,Math.Max(anchor.X,p.X)/1280);else if(handle>=0){b=original;if(handle is 0 or 6 or 7)b=b with{Left=original.Left+dx};if(handle is 2 or 3 or 4)b=b with{Right=original.Right+dx};if(handle is 0 or 1 or 2)b=b with{Top=original.Top+dy};if(handle is 4 or 5 or 6)b=b with{Bottom=original.Bottom+dy};}else{dx=Math.Clamp(dx,-original.Left,1-original.Right);dy=Math.Clamp(dy,-original.Top,1-original.Bottom);b=new(original.Top+dy,original.Bottom+dy,original.Left+dx,original.Right+dx);}b=ReadingArea.Bound(b);areas[list.SelectedIndex]=dragOutput?a with{Output=b,Appearance=(a.Appearance??new()) with{Position="custom"}}:a with{Source=b};UpdateCoordinates();Render();}
    private void End(){if(!dragging)return;dragging=false;draw=false;Save();LoadSelection();}
}
